package admin

import (
	_ "embed"
	"net/http"
)

// alpineVersion is the Alpine.js release bundled in assets/alpine.js. The
// file is the same bundle the PHP edition serves (src/Admin/AdminAssets.php,
// generated by scripts/vendor-alpine.php): @alpinejs/ui, @alpinejs/focus and
// alpinejs, in that order.
//
// The admin UI must not load script from a CDN: its pages show S3 secrets.
const alpineVersion = "3.17.5"

//go:embed assets/alpine.js
var alpineJS []byte

// alpinePath is the URL the admin pages load Alpine from. The version in the
// path lets browsers cache it forever.
const alpinePath = "/_/assets/alpine-" + alpineVersion + ".js"

func serveAlpine(w http.ResponseWriter) {
	h := w.Header()
	h.Set("Content-Type", "text/javascript; charset=UTF-8")
	h.Set("Cache-Control", "public, max-age=31536000, immutable")
	h.Set("X-Content-Type-Options", "nosniff")
	w.WriteHeader(http.StatusOK)
	w.Write(alpineJS)
}
